lNo,Trs_Del1.EwayBillDt,Pro_ReqKnitt2.Cost,Mas_Exporter.GSTNo,Mas_Buyer.GSTNo,Mas_Vehicle.VName,Trs_Salinv.ReverseCharge,Trs_Salinv.TransPortationMode,Trs_Del2.Rate,Mas_Count.BrandedFlag,Mas_HSN.UnitRate,Mas_HSN.NBPercH,MaS_HSN.NBPercL,Mas_HSN.BPercH,Mas_HSN.BPercL,Mas_Fabric.BrandedFlag,Mas_HSN2.UnitRate,Mas_HSN2.NBPercH,MaS_HSN2.NBPercL,Mas_HSN2.BPercH,Mas_HSN2.BPercL,Mas_HSN2.HSNCode,MAs_HSN3.UnitRate,MAs_HSN3.NBPercH,MAs_HSN3.NBPercL,MAs_HSN3.BPercH,MAs_HSN3.BPercL,MAs_HSN3.HSNCode,Mas_Exporter.ExporterAddress,Mas_Acc.BrandedFlag,ordermas.Jobno,OrderMas.Finyear, OrderMas.BuyOrdNo, ordermas.OrdId,IsNull(Mas_Bank.CurrAcc,'''')  ,IsNull(Mas_Bank.IFSCCode,''''),IsNull(CostName,'''') ,Trs_Salinv.InvType,Sales_Inv_Yarn_Prefix,Sales_Inv_Fabric_Prefix,Sales_Inv_Acc_Prefix,Trs_Salinv.Invno,Mas_HSN4.UnitRate,Mas_HSN4.NBPercH,MaS_HSN4.NBPercL,Mas_HSN4.BPercH,Mas_HSN4.BPercL,MAs_HSN4.HSNCode,Acc_PO_HSN_Detail.HSNID,isnull(Mas_AccDes.AccDescription,''''),Trs_Salinv.Remarks,Mas_AccDes.AccDescription,SuppOrdMas.SuppNo,SuppOrdMas.SuppFyr,IsNull(Mas_Bank.BankName,''''), isNull(Mas_Uom.Uom,''KGS''),DeliveryAddress, Case when isNull(Trs_Salinv.InvType,''Y'') =''F'' then StockTable.FinGsm Else 0 End, Case when isNull(Trs_Salinv.InvType,''Y'') =''F'' then  Mas_Dia.Dia Else '''' End,ISNULL(Trs_Salinv.DelAt,0) , ISNULL(DelAtParty.Pname,'''') ,  ISNULL(DelAtParty.GSTNo,'''') ,  ISNULL(DelAtState.StateName,''''),  ISNULL(DelAtState.StateCode,'''')  ,ISNULL(Mas_RateUom.Uom,''KGS'') , Trs_Del4.CGSTper,Trs_Del4.SGSTper,Trs_Del4.IGSTper,Mas_HSN_1.HSNCode,ISNULL(Trs_Del4.HSNID,0) ,Mas_buyer.Stateid,mas_buyer.buyeraddress '

EXEC sp_executesql @sql1 

END


